}];

const source = $('Resolve Dependencies').item.json;
const response = $json.body ?? $json;
const issues = Array.isArray(response) ? response : [];
const metadata = (body, key) => {
  const match = String(body || '').match(new RegExp(`<!--\\s*${key}:([^>]+?)\\s*-->`, 'i'));
  return match ? match[1].trim() : null;
};
const existing = issues.find((issue) =>
  metadata(issue.body, 'classroom-message-id') === source.gmailMessageId &&
  metadata(issue.body, 'issue-key') === source.issue.key
);
if (existing) {
  const staticData = $getWorkflowStaticData('global');
  staticData.classroomRuns[source.runKey].numbers[source.issue.key] = existing.number;
}
return [{
  json: {
    ...source,
    skipCreate: Boolean(existing || source.skipCreate),
    issueNumber: existing?.number || source.issueNumber || null,
  },
}];

const source = $('Apply Issue Recheck').item.json;
const response = $json.body ?? $json;
const number = response.number || source.issueNumber;
if (!number) throw new Error(`No se pudo reconciliar la Issue existente ${source.issue.key}`);
const staticData = $getWorkflowStaticData('global');
const state = staticData.classroomRuns[source.runKey];
state.numbers[source.issue.key] = number;
state.updatedAt = new Date().toISOString();
return [{ json: { runKey: source.runKey, key: source.issue.key, number, created: false, reconciled: true } }];

const source = $('Resolve Dependencies').item.json;
const response = $json.body ?? $json;
if (!response.number) throw new Error(`GitHub no devolvió número para ${source.issue.key}`);
const staticData = $getWorkflowStaticData('global');
const state = staticData.classroomRuns[source.runKey];
state.numbers[source.issue.key] = response.number;
state.updatedAt = new Date().toISOString();
return [{ json: { runKey: source.runKey, key: source.issue.key, number: response.number, created: true } }];

const planData = $('Plan and Topological Sort').item.json;
const response = $json.body ?? $json;
const issues = Array.isArray(response) ? response : [];
const metadata = (body, key) => {
  const match = String(body || '').match(new RegExp(`<!--\\s*${key}:([^>]+?)\\s*-->`, 'i'));
  return match ? match[1].trim() : null;
};
const matching = issues.filter((issue) =>
  metadata(issue.body, 'classroom-message-id') === planData.gmailMessageId &&
  metadata(issue.body, 'course') === planData.course &&
  metadata(issue.body, 'week') === planData.weekPadded
);
const byKey = Object.fromEntries(matching.map((issue) => [metadata(issue.body, 'issue-key'), issue]));
const missing = planData.planKeys.filter((key) => !byKey[key]);
if (missing.length) throw new Error(`Verificación falló; faltan Issues: ${missing.join(', ')}. Gmail NO fue marcado.`);
const configurationErrors = [];
for (const expected of planData.plan.issues) {
  const actual = byKey[expected.key];
  const assignees = (actual.assignees || []).map((assignee) => assignee.login);
  const labels = (actual.labels || []).map((label) => label.name || label);
  const expectedLabels = [planData.course, `week-${planData.weekPadded}`, `type:${expected.type}`, `priority:${expected.priority}`];
  if (!assignees.includes(expected.assignee)) configurationErrors.push(`${expected.key}: falta assignee ${expected.assignee}`);
  for (const label of expectedLabels) if (!labels.includes(label)) configurationErrors.push(`${expected.key}: falta label ${label}`);
  if (!metadata(actual.body, 'plan-keys')) configurationErrors.push(`${expected.key}: falta plan-keys`);
}
if (configurationErrors.length) throw new Error(`Verificación de Issues falló: ${configurationErrors.join('; ')}. Gmail NO fue marcado.`);
const assignments = { Draggodeidad: 0, JulianDele: 0, osbaldoXxC: 0 };
for (const issue of planData.plan.issues) assignments[issue.assignee] += 1;
return [{
  json: {
    ...planData,
    verifiedIssues: planData.planKeys.map((key) => ({ key, number: byKey[key].number, title: byKey[key].title })),
    assignments,
    verified: true,
  },
}];

const data = $json;
const issueLines = data.verifiedIssues.map((issue) => `${issue.key}: #${issue.number} ${issue.title}`).join('
');
return [{
  json: {
    ...data,
    notificationSubject: `✅ ${data.course} Semana ${data.weekPadded} procesada`,
    notificationBody: `✅ Semana ${data.weekPadded} procesada

Materia: ${data.course}
Repositorio: ${data.repository}
Actividad: ${data.plan.assignmentTitle}
Deadline: ${data.plan.deadline || 'No indicada'}

Issues verificadas: ${data.verifiedIssues.length}

Draggodeidad: ${data.assignments.Draggodeidad}
JulianDele: ${data.assignments.JulianDele}
osbaldoXxC: ${data.assignments.osbaldoXxC}

${issueLines}

Actividad marcada como procesada.`,
  },
}];
